CREATE DATABASE IF NOT EXISTS `amma` DEFAULT CHARACTER SET latin1 COLLATE latin1_swedish_ci;
USE `amma`;

DELIMITER $$
--
-- Funciones
--
CREATE DEFINER=`root`@`localhost` FUNCTION `getConflictoIntereses` (`user` INT(11)) RETURNS VARCHAR(255) CHARSET latin1 BEGIN

DECLARE clientes varchar(255);

SELECT GROUP_CONCAT(CONCAT("'",uc.no_cliente),"'") INTO clientes
FROM usuarios_conflicto uc
WHERE (uc.estatus_interno = 1) AND uc.id_usuario = user
GROUP BY uc.id_usuario
ORDER BY uc.no_cliente;

IF clientes IS NOT NULL THEN
    RETURN clientes;
ELSE 
	RETURN "";
END IF ;

END$$

