--
-- Disparadores `h_pedidos`
--
DELIMITER $$
CREATE TRIGGER `h_pedidos_AI_TRIGGER` AFTER INSERT ON `h_pedidos` FOR EACH ROW BEGIN
    IF NEW.id_sh_d!=0  THEN
    UPDATE sh_detalle set sh_detalle.status=4 WHERE sh_detalle.id=NEW.id_sh_d;
    END IF;
 END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `h_pedidos_AU_TRIGGER` AFTER UPDATE ON `h_pedidos` FOR EACH ROW BEGIN

    IF NEW.id_sh_d!=0 AND NEW.status=4  THEN

    UPDATE sh_detalle set sh_detalle.status=6 WHERE sh_detalle.id=OLD.id_sh_d;

    ELSEIF NEW.id_sh_d!=0 AND NEW.status=6  THEN

    UPDATE sh_detalle set sh_detalle.status=5 WHERE sh_detalle.id=OLD.id_sh_d;

    END IF;

 END
$$
DELIMITER ;

