INSERT INTO `clientes` (`no_cliente`, `registro_crm`, `asociado`, `registro`, `nombre`, `rfc`, `calle`, `noexterior`, `nointerior`, `colonia`, `municipio`, `cp`, `telefono`, `fax`, `correo`, `rep_legal`, `folio_cred_rep_legal`, `tipo_persona`, `magueyero`, `mezcalero`, `envasador`, `comercializador`, `comercializador_bc`, `viverista`, `comercializador_regional`, `organizacion`, `trab_hombres`, `trab_mujeres`, `trab_discapacitados`, `domicilio`, `contrasenia`, `dom`, `per_autorizada`, `carpetaUnica`, `status`, `beca`, `identificacion`, `actualizado`, `ultimaModificacion`, `fechaUltimaModif`, `datosActaPoder`, `objetoSocial`, `comentarios`, `revision`, `autorizado`, `noticia`, `notas_uaa`, `fecha_suspencion`, `es_extranjero`, `delegado`, `ocultar`) VALUES
('C0001', '0193', 1, '2021-08-24', 'PRODUCTORES DE MAGUEY Y MEZCAL GUIEU-HSCUE S.P.R. DE R.I.', 'PMY090710I12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 1, 1, 1, 1, 0, 0, 0, '', 10, 7, 0, NULL, '', NULL, NULL, '611ff410b3dc0', 1, 0, NULL, 1, 21, '2021-08-24 17:04:49', 'ACTA CONSTITUTIVA CON INSTRUMENTO NÚMERO 8683 (OCHO MIL SEISCIENTOS OCHENTA Y TRES) VOLUMEN 127 (CIENTO VEINTISIETE) DE FECHA 10 (DIEZ) DE JULIO DE 2009 (DOS MIL NUEVE) PASADA ANTE LA FE DE LA LIC. MARTHA PAZOS ORTIZ, NOTARIO PÚBLICO NÚMERO 40 (CUARENTA) EN EJERCICIO EN EL ESTADO DE OAXACA Y CON RESIDENCIA EN LA CAPITAL DEL ESTADO.  RATIFICACIÓN DE PODERES DEL REPRESENTANTE LEGAL CON INSTRUMENTO 11,109 (ONCE MIL CIENTO NUEVE) VOLUMEN 43 (CUARENTA Y TRES) DE FECHA 23 (VEINTITRES) DE SEPTIEMBRE DE 2016 (DOS MIL DIECISEIS) PASADO ANTE LA FE DEL LIC. YAIR LOPEZ HERNANDEZ, NOTARIO PÚBLICO NÚMERO 101 (CIENTO UNO) EN EJERCICIO EN EL ESTADO DE OAXACA Y CON RESIDENCIA EN LA CIUDAD DE EJUTLA DE CRESPO.', 'LA PRODUCCIÓN, COMERCIALIZACIÓN, INDUSTRIALIZACIÓN, EMPAQUE, GESTIÓN, MEDIACIÓN, COMPRA, VENTA, IMPORTACIÓN, EXPORTACIÓN, COMISIÓN, CONSIGNACIÓN, MANUFACTURA Y MAQUILA  DE TODA CLASE DE MAGUEY MEZCALERO, ASÍ COMO TODO LO INHERENTE CON LA AGRICULTURA Y FLORICULTURA.', '', 1, 0, 1, NULL, NULL, 0, 0, 0),
('C0002', '0296', 1, '2021-08-24', 'DESCENDIENTES DE PRODUCTORES DE MEZCAL DON MAURO Y PEDRO LÓPEZ SPR DE RI', 'DDP1106039E6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 1, 1, 1, 1, 0, 0, 0, NULL, 5, 0, 0, NULL, '', NULL, NULL, '61241fd444505', 1, 0, NULL, 1, 121, '2021-08-24 22:15:53', 'INSTRUMENTO NÚMERO OCHO MIL NOVECIENTOS SESENTA Y DOS (8962), LIBRO DE SOCIEDADES MERCANTILES NÚMERO UNO; EN LA CIUDAD DE OAXACA DE JUÁREZ, OAXACA, CAPITAL DEL ESTADO DE OAXACA DEL DÍA TRES DE JUNIO DEL AÑO DOS MIL ONCE; ANTE EL LICENCIADO ZENON LÓPEZ LÓPEZ, CORREDOR PÚBLICO TITULAR DE LA CORREDURÍA PÚBLICA NÚMERO DOS', 'EL APROVECHAMIENTO DE LOS RECURSOS NATURALES DESARROLLANDO ACTIVIDADES AGROPECUARIAS, AGRÍCOLAS, GANADERAS, APÍCOLAS, SOLVÍCOLAS, FORESTALES, PRODUCCIÓN DE PLANTAS EN VIVEROS, SIEMBRA Y PRODUCCIÓN DE MAGUEY DE MEZCAL EN SUS DIFERENTES TIPOS, PRODUCCIÓN DE MEZCAL EN SUS DIFERENTES VARIEDADES, ASÍ COMO SU VENTA, TRANSPORTE, ALMACENAMIENTO, COMERCIALIZACIÓN Y EXPORTACIÓN; ELABORACIÓN DE TODO TIPO DE ARTESANÍAS, PRODUCCIÓN, COMERCIALIZACIÓN Y VENTA DE PRODUCTOS ALIMENTICIOS INCLUYENDO LA ELABORACIÓN DE ALIMENTOS Y SERVICIO DE RESTAURANT EN TODAS SUS MODALIDADES; LA GENERACIÓN DE EMPLEOS, PARA LOS SOCIOS Y HABITANTES DE LA COMUNIDAD, ADQUISICIÓN DE MAQUINARIA, TECNOLOGÍA Y CAPACITACIÓN; ASÍ COMO LA COMERCIALIZACIÓN DE LOS MISMOS LOGRANDO CON ELLO EL MEJORAMIENTO DE LA ECONOMÍA PARA EL BIENESTAR DE LAS FAMILIAS DE LOS SOCIOS. ', '', 1, 0, 1, 'FALTA ACTUALIZAR LA SIGUIENTE DOCUMENTACIÓN: \n1.- Actualización de la Constancia de Razón Social\n2.- Comprobante de domicilio\n3.- Carta de Designación de Persona Autorizada (comparto formato)\n4.- Opinión de cumplimiento\n5.- Ratificación del presidente, secretario y tesorero de la persona moral, acta notariada\n6.- Identificación del Arrendador vigente (Fabrica 1, envasadora 1, bodega 1)\n \nFabrica 2: a) Comprobante de posesión, b) contrato de arrendamiento, c) identificación oficial de persona responsable, d) identificación de arrendatario y arrendador.', NULL, 0, 0, 0),
('C0004', '0066', 0, '2021-08-24', 'GRUPO YUU BAAL, S.A. DE C.V.', 'GYB051226837', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 1, 1, 1, 1, 0, 0, 0, NULL, 5, 0, 0, NULL, '', NULL, NULL, '6123f5301c363', 1, 0, NULL, 1, 122, '2021-08-24 22:03:28', 'ACTA CONSTITUTIVA CON INSTRUMENTO NUMERO 44494 (CUARENTA Y CUATRO MIL CUATROSCIENTOS NOVENTA Y CUATRO) VOLUMEN 593 (QUINIENTOS NOVENTA Y TRES) DE FECHA 26 (VEINTISEIS) DE DICIEMBRE DE 2005 (DOS MIL CINCO) PASADA ANTE LA FE DEL LIC. OCTAVIO MANZANO TROVAMALA NAVA , NOTARIO PUBLICO NUMERO 15 (QUINCE) EN EJERCICIO EN EL ESTADO DE OAXACA Y CON RESIDENCIA EN LA CAPITAL DEL ESTADO. RACTIFICACION DE PODERES DEL REPRESENTANTE LEGAL CON INSTRUMENTO 6398 (SEIS MIL TRESCIENTOS NOVENTA Y OCHO) VOLUMEN 114 (CIENTO CATORCE) DE FECHA 16 (DIECISEIS) DE ENERO DE 2020 (DOS MIL VEINTE) PASADO ANTE LA FE DEL LIC. MIGUEL ANGEL GUZMAN LABASTIDA, NOTARIO PÚBLICO NÚMERO 33 (TREINTA Y TRES) EN EJERCICIO EN EL ESTADO DE OAXACA Y CON RESIDENCIA EN LA CAPITAL DEL ESTADO.', '1. LA COMPRA DE MEZCAL A LOS PRODUCTORES DE LA REGIÓN, PARA SU DESTILACIÓN Y EL ENVASADO DEL MISMO PARA SU COMERCIALIZACIÓN TANTO A NIVEL NACIONAL COMO INTERNACIONAL. 2. LA SIEMBRA, COSECHA, EXPLOTACIÓN E INDUSTRIALIZACIÓN DEL MAGUEY, PARA LA OBTENCIÓN DE DIFERENTES PRODUCTOS, ENTRE ELLOS EL MEZCAL, PARA SU ENVASADO Y COMERCIALIZACIÓN, TANTO A NIVEL NACIONAL COMO INTERNACIONAL. ', '', 1, 0, 1, NULL, NULL, 0, 0, 0),
('C0005', '0105', 1, '2021-08-25', 'MEZCAL EL REY ZAPOTECO, S.A. DE C.V.', 'MRZ130208PX3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 1, 1, 1, 1, 0, 0, 0, '', 6, 3, 0, NULL, '', NULL, NULL, '612417e434b8e', 1, 0, NULL, 1, 69, '2021-08-25 18:54:36', 'ACTA DE LA ASAMBLEA GENERAL ORDINARIO DE ACCIONISTAS DE FECHA DOS DE MAYO DEL AÑO DOS MIL DICINUEVE PASADA ANTE LA FE DEL DOCTOR EN DERECHO ARTURO DAVID VÁSQUEZ URDIALES, NOTARIO PUBLICO NÚMERO CIEN, EN EL ESTADO DE OAXACA', 'SEMBRAR, COSECHAR, VENDER, COMPRAR, IMPORTAR, EXPORTAR, ENVASAR, PRODUCIR Y COMERCIALIZAR AGAVE, Y PRODUCTOS DERIVADOS DEL AGAVE, DESTILADOS DE AGAVE, INCLUIDO MAS NO LIMITADO, AL MEZCAL Y MIEL DE AGAVE, ENTRE OTROS DE LOS DERIVADOS DEL AGAVE', '', 1, 0, 1, NULL, NULL, 0, 0, 0),
